// Generated automatically by GitHub Actions. Do not edit manually.\nwindow.ENGLISH_MASTER_WEEKLY = [{"id":"weekly-2026-w47-daily-a1","title":"New this week · Daily Conversation · A1","vi":"Bài học mới hàng tuần · Giao tiếp hàng ngày","level":"A1","track":"daily","icon":"✨","note":"50 câu mới của tuần 2026-W47 được chia theo cấp độ. Đây là nội dung nguyên bản, tham khảo định hướng học tập CEFR.","formula":"Useful phrases in context","signals":"Listen · Understand · Repeat · Use","items":[{"en":"My sister has a small white cat.","vi":"Em gái tôi có một con mèo trắng nhỏ.","explain":"Cấu trúc cơ bản 'has a' dùng để diễn tả việc sở hữu đồ vật hoặc thú cưng ở mức độ sơ cấp.","topic":"Family and home"},{"en":"I usually drink water with my meal.","vi":"Tôi thường uống nước lọc trong bữa ăn của mình.","explain":"Trạng từ chỉ tần suất 'usually' đứng trước động từ thường 'drink'.","topic":"Food and drink"},{"en":"We like listening to music in the evening.","vi":"Chúng tôi thích nghe nhạc vào buổi tối.","explain":"Cấu trúc 'like' đi với động từ thêm đuôi '-ing' để diễn tả sở thích chung.","topic":"Hobby and leisure"},{"en":"How much does this red shirt cost?","vi":"Chiếc áo sơ mi đỏ này giá bao nhiêu?","explain":"Câu hỏi quen thuộc 'How much does... cost?' dùng khi mua sắm để hỏi giá tiền.","topic":"Shopping"},{"en":"She walks to her school every single day.","vi":"Cô ấy đi bộ đến trường mỗi ngày.","explain":"Cụm từ 'every single day' nhấn mạnh tính đều đặn của thói quen hằng ngày.","topic":"Daily routine"},{"en":"It is cold and windy outside right now.","vi":"Trời bên ngoài đang lạnh và có gió ngay lúc này.","explain":"Sử dụng tính từ miêu tả thời tiết 'cold' và 'windy' kết hợp với trạng từ chỉ thời điểm 'right now'.","topic":"Weather"},{"en":"There is a large park near our house.","vi":"Có một công viên lớn gần nhà chúng tôi.","explain":"Cấu trúc 'There is' dùng để giới thiệu sự tồn tại của sự vật ở một địa điểm.","topic":"Town and city"},{"en":"He drinks hot tea when he feels cold.","vi":"Anh ấy uống trà nóng khi cảm thấy lạnh.","explain":"Mệnh đề chỉ thời gian với từ 'when' ở thì hiện tại đơn diễn tả một thói quen hiển nhiên.","topic":"Health"}]},{"id":"weekly-2026-w47-daily-a2","title":"New this week · Daily Conversation · A2","vi":"Bài học mới hàng tuần · Giao tiếp hàng ngày","level":"A2","track":"daily","icon":"✨","note":"50 câu mới của tuần 2026-W47 được chia theo cấp độ. Đây là nội dung nguyên bản, tham khảo định hướng học tập CEFR.","formula":"Useful phrases in context","signals":"Listen · Understand · Repeat · Use","items":[{"en":"We missed the early train because of heavy traffic.","vi":"Chúng tôi đã lỡ chuyến tàu sớm vì kẹt xe nặng.","explain":"Cụm từ 'because of' dùng để chỉ nguyên nhân dẫn đến sự việc ở thì quá khứ.","topic":"Travel and transport"},{"en":"Are you doing anything special for your birthday?","vi":"Bạn có làm gì đặc biệt cho ngày sinh nhật của mình không?","explain":"Thì hiện tại tiếp diễn 'Are you doing' được dùng với nghĩa tương lai để hỏi về kế hoạch cá nhân.","topic":"Social interaction"},{"en":"I plan to visit my grandparents next month.","vi":"Tôi dự định đến thăm ông bà vào tháng tới.","explain":"Động từ 'plan to' theo sau bởi nguyên thể chỉ dự định trong tương lai gần.","topic":"Holidays and plans"},{"en":"Could you pass me the salt and pepper, please?","vi":"Làm ơn chuyển cho tôi lọ muối và tiêu được không?","explain":"Câu đề nghị lịch sự sử dụng 'Could you...' để nhờ ai đó giúp đỡ việc nhỏ trong bữa ăn.","topic":"Food and cooking"},{"en":"She enjoys reading mystery novels on rainy weekends.","vi":"Cô ấy thích đọc tiểu thuyết trinh thám vào những ngày cuối tuần mưa gió.","explain":"Động từ 'enjoy' đi với danh động từ 'reading' để chỉ sở thích lâu dài.","topic":"Entertainment"},{"en":"We need to clean the living room before guests arrive.","vi":"Chúng ta cần dọn dẹp phòng khách trước khi khách đến.","explain":"Cấu trúc 'need to' thể hiện sự cần thiết phải làm một việc gì đó.","topic":"House and home"},{"en":"I would like to return this jacket for a smaller size.","vi":"Tôi muốn đổi trả chiếc áo khoác này lấy cỡ nhỏ hơn.","explain":"Mẫu câu lịch sự 'I would like to' dùng khi đưa ra yêu cầu đổi hàng tại cửa hàng.","topic":"Shopping and services"},{"en":"Jogging every morning helps me stay active and healthy.","vi":"Chạy bộ mỗi buổi sáng giúp tôi duy trì sự năng động và khỏe mạnh.","explain":"Danh động từ 'Jogging' làm chủ ngữ cho câu diễn tả lợi ích của việc tập luyện.","topic":"Health and fitness"},{"en":"He practices speaking English with native speakers online.","vi":"Anh ấy luyện tập nói tiếng Anh với những người bản xứ trực tuyến.","explain":"Động từ 'practice' đi với động từ thêm '-ing' để chỉ hoạt động luyện tập kỹ năng.","topic":"Education and learning"}]},{"id":"weekly-2026-w47-daily-b1","title":"New this week · Daily Conversation · B1","vi":"Bài học mới hàng tuần · Giao tiếp hàng ngày","level":"B1","track":"daily","icon":"✨","note":"50 câu mới của tuần 2026-W47 được chia theo cấp độ. Đây là nội dung nguyên bản, tham khảo định hướng học tập CEFR.","formula":"Useful phrases in context","signals":"Listen · Understand · Repeat · Use","items":[{"en":"I strongly believe that regular exercise improves mental health.","vi":"Tôi hoàn toàn tin rằng việc tập thể dục đều đặn cải thiện sức khỏe tinh thần.","explain":"Cụm từ 'strongly believe' giúp thể hiện quan điểm cá nhân một cách rõ ràng và thuyết phục.","topic":"Personal opinions"},{"en":"If we book the tickets early, we can save a lot of money.","vi":"Nếu chúng ta đặt vé sớm, chúng ta có thể tiết kiệm được rất nhiều tiền.","explain":"Câu điều kiện loại 1 diễn tả một giả định có thật và kết quả có thể xảy ra ở hiện tại hoặc tương lai.","topic":"Travel experiences"},{"en":"Although it started raining, we still enjoyed our picnic.","vi":"Mặc dù trời bắt đầu mưa, chúng tôi vẫn tận hưởng buổi dã ngoại của mình.","explain":"Liên từ 'Although' dùng để nối hai mệnh đề có ý nghĩa tương phản nhau.","topic":"Problem-solving"},{"en":"She decided to reduce her sugar intake to feel more energetic.","vi":"Cô ấy quyết định giảm lượng đường nạp vào để cảm thấy tràn đầy năng lượng hơn.","explain":"Cấu trúc 'decided to' đi với mục đích 'to feel...' giải thích lý do của hành động.","topic":"Lifestyle changes"},{"en":"Good communication is essential for maintaining strong friendships.","vi":"Giao tiếp tốt là yếu tố cốt lõi để duy trì những tình bạn bền chặt.","explain":"Tính từ 'essential' kết hợp với giới từ 'for' và danh động từ 'maintaining'.","topic":"Relationships"},{"en":"Many people are now using reusable bags to reduce plastic waste.","vi":"Nhiều người hiện đang sử dụng túi có thể tái sử dụng để giảm thiểu rác thải nhựa.","explain":"Thì hiện tại tiếp diễn diễn tả xu hướng đang thay đổi trong xã hội hiện nay.","topic":"Environment"},{"en":"Streaming services have completely changed how we watch movies.","vi":"Các dịch vụ phát trực tuyến đã thay đổi hoàn toàn cách chúng ta xem phim.","explain":"Thì hiện tại hoàn thành diễn tả hành động bắt đầu trong quá khứ và có ảnh hưởng đến hiện tại.","topic":"Media and technology"},{"en":"By next year, I hope to have saved enough money for a long trip.","vi":"Tính đến năm tới, tôi hy vọng đã tiết kiệm đủ tiền cho một chuyến đi dài ngày.","explain":"Thì tương lai hoàn thành 'to have saved' nhấn mạnh hành động sẽ hoàn thành trước một mốc thời gian.","topic":"Future ambitions"}]},{"id":"weekly-2026-w47-work-a1","title":"New this week · English for Work · A1","vi":"Bài học mới hàng tuần · Tiếng Anh công việc","level":"A1","track":"work","icon":"💼","note":"50 câu mới của tuần 2026-W47 được chia theo cấp độ. Đây là nội dung nguyên bản, tham khảo định hướng học tập CEFR.","formula":"Useful phrases in context","signals":"Listen · Understand · Repeat · Use","items":[{"en":"Please print this document for the meeting.","vi":"Làm ơn in tài liệu này cho cuộc họp.","explain":"Câu mệnh lệnh lịch sự với từ 'Please' dùng phổ biến trong môi trường công sở.","topic":"Office basics"},{"en":"Our weekly team meeting starts at nine.","vi":"Cuộc họp nhóm hàng tuần của chúng ta bắt đầu lúc chín giờ.","explain":"Sử dụng thì hiện tại đơn để nói về lịch trình cố định hoặc thời gian biểu.","topic":"Schedules"},{"en":"Send me an email with your new phone number.","vi":"Gửi cho tôi một email kèm theo số điện thoại mới của bạn.","explain":"Mẫu câu yêu cầu cơ bản trong công việc với động từ nguyên mẫu đứng đầu câu.","topic":"Communication"},{"en":"Where is the blue pen on the desk?","vi":"Cây bút màu xanh trên bàn ở đâu vậy?","explain":"Câu hỏi vị trí cơ bản sử dụng từ để hỏi 'Where' và giới từ chỉ địa điểm 'on'.","topic":"Office items"},{"en":"She answers customer calls every single morning.","vi":"Cô ấy trả lời các cuộc gọi của khách hàng vào mọi buổi sáng.","explain":"Thì hiện tại đơn diễn tả công việc lặp đi lặp lại của nhân viên.","topic":"Workplace tasks"},{"en":"Turn off your monitor before you leave work.","vi":"Hãy tắt màn hình máy tính của bạn trước khi rời khỏi nơi làm việc.","explain":"Cụm động từ 'Turn off' dùng để chỉ hành động tắt thiết bị điện tử.","topic":"IT support basics"},{"en":"Mark works in the sales department downtown.","vi":"Mark làm việc tại phòng kinh doanh ở trung tâm thành phố.","explain":"Giới từ 'in' đi kèm với tên bộ phận hoặc phòng ban trong công ty.","topic":"Colleagues"},{"en":"We need more paper for the copy machine.","vi":"Chúng ta cần thêm giấy cho máy photocopy.","explain":"Cụm danh từ 'copy machine' chỉ thiết bị văn phòng dùng để sao chụp tài liệu.","topic":"Office supplies"}]},{"id":"weekly-2026-w47-work-a2","title":"New this week · English for Work · A2","vi":"Bài học mới hàng tuần · Tiếng Anh công việc","level":"A2","track":"work","icon":"💼","note":"50 câu mới của tuần 2026-W47 được chia theo cấp độ. Đây là nội dung nguyên bản, tham khảo định hướng học tập CEFR.","formula":"Useful phrases in context","signals":"Listen · Understand · Repeat · Use","items":[{"en":"We finished the marketing report ahead of schedule.","vi":"Chúng tôi đã hoàn thành báo cáo tiếp thị trước thời hạn.","explain":"Cụm từ 'ahead of schedule' có nghĩa là hoàn thành công việc sớm hơn dự kiến.","topic":"Project updates"},{"en":"I will forward the attachment to your inbox shortly.","vi":"Tôi sẽ chuyển tiếp tệp đính kèm vào hộp thư của bạn sớm thôi.","explain":"Động từ 'forward' kết hợp với danh từ 'attachment' rất hay dùng khi trao đổi email.","topic":"Email etiquette"},{"en":"Check the ethernet cable if your internet connection drops.","vi":"Hãy kiểm tra cáp mạng nếu kết nối internet của bạn bị rớt.","explain":"Câu mệnh lệnh kết hợp với từ 'if' dùng để đưa ra hướng dẫn khắc phục sự cố mạng đơn giản.","topic":"Network troubleshooting"},{"en":"Can we reschedule our discussion to Thursday afternoon?","vi":"Chúng ta có thể dời lịch thảo luận sang chiều thứ Năm được không?","explain":"Động từ 'reschedule' nghĩa là thay đổi lịch hẹn đã định sẵn một cách lịch sự.","topic":"Meetings"},{"en":"Let me check the system status for your account.","vi":"Để tôi kiểm tra trạng thái hệ thống cho tài khoản của bạn.","explain":"Cấu trúc 'Let me...' dùng khi người nói muốn chủ động thực hiện một hành động giúp đỡ khách hàng.","topic":"Customer service"},{"en":"Please submit your travel expenses by Friday afternoon.","vi":"Vui lòng nộp chi phí công tác của bạn trước chiều thứ Sáu.","explain":"Động từ 'submit' mang nghĩa nộp hoặc gửi tài liệu, báo cáo theo quy định.","topic":"Office administration"},{"en":"The printer is out of ink, so we cannot print today.","vi":"Máy in đã hết mực, vì vậy chúng ta không thể in tài liệu hôm nay.","explain":"Cấu trúc nguyên nhân kết quả sử dụng liên từ 'so' để giải thích tình trạng thiết bị.","topic":"Hardware support"},{"en":"She shared the collaborative folder with all team members.","vi":"Cô ấy đã chia sẻ thư mục làm việc chung với tất cả các thành viên trong nhóm.","explain":"Tính từ 'collaborative' chỉ tính chất hợp tác, chia sẻ tài nguyên chung trong công việc.","topic":"Team collaboration"},{"en":"Remember to log out of your workstation when you leave.","vi":"Nhớ đăng xuất khỏi trạm làm việc của bạn khi bạn rời đi.","explain":"Cụm từ 'log out of' rất quan trọng về vấn đề bảo mật an ninh thông tin văn phòng.","topic":"Workplace instructions"}]},{"id":"weekly-2026-w47-work-b1","title":"New this week · English for Work · B1","vi":"Bài học mới hàng tuần · Tiếng Anh công việc","level":"B1","track":"work","icon":"💼","note":"50 câu mới của tuần 2026-W47 được chia theo cấp độ. Đây là nội dung nguyên bản, tham khảo định hướng học tập CEFR.","formula":"Useful phrases in context","signals":"Listen · Understand · Repeat · Use","items":[{"en":"We must prioritize these tasks to meet the upcoming deadline.","vi":"Chúng ta phải ưu tiên các nhiệm vụ này để kịp thời hạn sắp tới.","explain":"Động từ 'prioritize' diễn tả việc sắp xếp thứ tự quan trọng cho các công việc trong dự án.","topic":"Project management"},{"en":"The system upgrade requires a brief server downtime tonight.","vi":"Việc nâng cấp hệ thống đòi hỏi thời gian ngừng hoạt động máy chủ ngắn vào tối nay.","explain":"Cụm danh từ 'server downtime' dùng trong kỹ thuật để chỉ thời điểm hệ thống tạm ngưng phục vụ.","topic":"IT infrastructure"},{"en":"I am writing to inquire about the status of our recent order.","vi":"Tôi viết thư này để hỏi thăm về tình trạng đơn hàng gần đây của chúng tôi.","explain":"Mẫu câu trang trọng 'I am writing to inquire about...' thường được dùng trong thư tín thương mại.","topic":"Professional communication"},{"en":"If the error persists, please escalate the support ticket to senior staff.","vi":"Nếu lỗi vẫn tiếp diễn, vui lòng chuyển phiếu hỗ trợ lên cấp nhân sự cao hơn.","explain":"Động từ 'escalate' chỉ hành động chuyển vấn đề lên cấp quản lý hoặc chuyên gia cấp cao hơn.","topic":"Problem escalation"},{"en":"My supervisor appreciated my contribution to the quarterly sales report.","vi":"Cấp quản lý của tôi đã đánh giá cao đóng góp của tôi vào báo cáo doanh số hàng quý.","explain":"Động từ 'appreciated' thể hiện sự ghi nhận và trân trọng thành quả làm việc.","topic":"Performance review"},{"en":"We need to analyze market trends before launching the new product.","vi":"Chúng ta cần phân tích xu hướng thị trường trước khi ra mắt sản phẩm mới.","explain":"Động từ 'analyze' kết hợp với cụm từ chỉ mục đích thực hiện nghiên cứu chiến lược kinh doanh.","topic":"Strategic planning"},{"en":"The IT department is configuring the new firewall settings for better security.","vi":"Phòng IT đang cấu hình các thiết lập tường lửa mới để bảo mật tốt hơn.","explain":"Thì hiện tại tiếp diễn diễn tả hành động kỹ thuật đang được thực hiện chuyên sâu tại công ty.","topic":"Network administration"},{"en":"Although our budget is limited, we can negotiate the contract terms.","vi":"Mặc dù ngân sách của chúng ta hạn hẹp, chúng ta vẫn có thể thương lượng các điều khoản hợp đồng.","explain":"Cấu trúc nhượng bộ với 'Although' giúp thể hiện kỹ năng đàm phán chuyên nghiệp trong kinh doanh.","topic":"Meeting negotiation"}]}];\n